import sys

def main():
    s = sys.stdin.readline().strip()
    left = 0
    cnt = 0
    best_len = 0
    best_start = 0
    for right, ch in enumerate(s):
        if ch == '#':
            cnt += 1
        while cnt > 1:
            if s[left] == '#':
                cnt -= 1
            left += 1
        if right - left + 1 > best_len:
            best_len = right - left + 1
            best_start = left
    print(s[best_start:best_start + best_len])

